pub(crate) fn rva(old: u64) -> u64 {
    ADDRESSES
        .iter()
        .find(|(a, _)| *a == old)
        .map(|(_, b)| *b)
        .expect("Unreviewed 0.139.2 address")
}
pub(crate) fn baseline(native: u64) -> u64 {
    ADDRESSES
        .iter()
        .find(|(_, b)| *b == native)
        .map(|(a, _)| *a)
        .unwrap_or(0)
}
pub(crate) fn expected(old: u64) -> &'static [u8] {
    ENTRIES
        .iter()
        .find(|(a, _)| *a == old)
        .map(|(_, b)| *b)
        .expect("Unreviewed 0.139.2 bytes")
}
